import{j as e}from"./index-BJEF3AA0.js";import{S as t}from"./ServicePageLayout-DjWDAuGa.js";import{H as n}from"./headphones-BANks_h6.js";import"./button-Cw0xvSQk.js";import"./PageBanner-BA44tIJw.js";import"./Breadcrumbs-DFM23V6R.js";import"./chevron-right-lYK8hZ14.js";function p(){return e.jsx(t,{"code-path":"src\\pages\\services\\ServiceDesk.tsx:6:5",title:"Service Desk",subtitle:"Unify Customer Support Across SMS, Email & WhatsApp",description:"Bring every customer conversation into one desk with MobiWave. Unify support across SMS, email and WhatsApp, route tickets, automate replies and track response times from a single Kenyan platform — with 24/7 local support and native bundling of your messaging and M-Pesa channels.",icon:n,stats:[{value:"SMS+Email+WA",label:"Unified Inbox"},{value:"Routing",label:"Smart Tickets"},{value:"SLA",label:"Tracking"},{value:"24/7",label:"Nairobi Support"}],features:["Unified inbox across SMS, email and WhatsApp","Ticket creation and assignment","Smart routing and agent queues","Canned responses and macros","SLA and response-time tracking","Automated replies and bots","Conversation history and context","CSAT and agent performance reports","Webhook and CRM integrations","Bundled with bulk SMS, USSD and M-Pesa"],benefits:["One place for every customer conversation","Faster first response with routing and macros","Consistent SLA and quality across channels","Full context and history per customer","Measure and improve agent performance","24/7 local Nairobi support via phone and WhatsApp"],useCases:[{title:"Multi-channel support",description:"Handle SMS, email and WhatsApp threads in one agent console."},{title:"Ticket routing",description:"Auto-assign incoming queries to the right team or agent."},{title:"Order & delivery help",description:"Resolve order, delivery and payment questions with full context."},{title:"Escalations",description:"Escalate SLA-breaching conversations with alerts."},{title:"Self-service + bot",description:"Automate common answers, hand off to humans when needed."},{title:"Field service coordination",description:"Coordinate technicians and customers from one desk."},{title:"SACCO & banking queries",description:"Manage member and customer queries with compliant history."},{title:"Government & NGO help lines",description:"Run citizen and beneficiary support across channels."}],howItWorks:[{step:"1",title:"Connect your channels",description:"Link SMS (sender ID), email and WhatsApp Business API to MobiWave. Inbound messages from all three land in one unified inbox."},{step:"2",title:"Configure routing",description:"Set up teams, agent queues and rules so each conversation is assigned by channel, topic or SLA priority."},{step:"3",title:"Create tickets",description:"Every conversation becomes a trackable ticket with history, context and SLA timers — no message lost between channels."},{step:"4",title:"Respond with context",description:"Agents reply using canned responses, macros and the full customer timeline, across SMS, email or WhatsApp."},{step:"5",title:"Automate & measure",description:"Deploy bots for common questions, then track CSAT, response times and agent performance in reports."},{step:"6",title:"Integrate & bundle",description:"Pipe tickets into your CRM via webhook and bundle the desk with bulk SMS, USSD and M-Pesa on one MobiWave account."}],comparisonTable:{headers:["MobiWave","Zendesk","Freshdesk","Help Scout"],note:"MobiWave unifies SMS, email and WhatsApp with native bundling to your MobiWave messaging and M-Pesa channels, plus 24/7 local Kenyan support. Global help desks are strong but lack local channel and payment bundling.",rows:[{name:"SMS + Email + WhatsApp inbox",cells:[{text:"Native, unified",highlight:!0},{text:"Add-ons"},{text:"Add-ons"},{text:"Add-ons"}]},{name:"Native M-Pesa / USSD bundle",cells:[{text:"One account",highlight:!0},{text:"No"},{text:"No"},{text:"No"}]},{name:"SLA & CSAT reporting",cells:[{text:"Yes",highlight:!0},{text:"Yes (paid tiers)"},{text:"Yes"},{text:"Yes"}]},{name:"Local KES billing & support",cells:[{text:"Yes, 24/7",highlight:!0},{text:"USD, no local team"},{text:"USD, no local team"},{text:"USD, no local team"}]}]},pricing:[{title:"Team",price:"Usage-based",unit:"",features:["Unified SMS/Email/WhatsApp inbox","Tickets + routing","Canned responses","Standard support"]},{title:"Pro",price:"Usage-based",unit:"",features:["Everything in Team","SLA & CSAT reporting","Automation & bots","Webhook / CRM integration","24/7 support"]},{title:"Enterprise",price:"Custom",unit:"",features:["High-volume teams","Custom SLAs","Multi-branch routing","Dedicated account manager"]}],faqs:[{question:"How much does the service desk cost?",answer:"MobiWave bills the service desk on a per-agent or usage basis depending on volume, with no setup fees. Because it is billed locally in KES and bundles your existing SMS, WhatsApp and M-Pesa channels, it is often simpler than a global help desk — contact us for current rates."},{question:"Which channels are unified?",answer:"The desk unifies SMS (your CAK-registered sender ID), email and the official WhatsApp Business API in one inbox, so agents handle every conversation from a single console."},{question:"Can I route tickets to different teams?",answer:"Yes. Configure teams, agent queues and rules so each conversation is assigned by channel, topic or SLA priority — with escalation alerts when SLAs are at risk."},{question:"Does it support automation and bots?",answer:"Yes. Deploy automated replies and bots for common questions, with smooth hand-off to a human agent when the conversation needs it."},{question:"How do you measure performance?",answer:"Built-in CSAT, response-time and agent-performance reports let you track SLA adherence and improve quality over time."},{question:"Can it integrate with our CRM?",answer:"Yes. Tickets and events post via webhook into your CRM or data warehouse, and conversation history is retained per customer for context."},{question:"Is customer data secure and compliant?",answer:"Yes. The desk runs on MobiWave’s secured platform with conversation history and opt-in handling aligned to ODPC data-protection expectations in Kenya."},{question:"Can agents reply on WhatsApp and SMS from one place?",answer:"Yes. An agent sees the full customer timeline and can reply on whichever channel the customer used — or switch channels — without leaving the desk."},{question:"Does it connect to M-Pesa?",answer:"Yes. On the same MobiWave account, an agent can trigger an M-Pesa STK Push or check payment context while handling a support ticket."},{question:"How is MobiWave different from Zendesk?",answer:"Zendesk is a powerful global help desk but is billed in USD, self-service, and lacks native Kenyan SMS/WhatsApp/M-Pesa bundling. MobiWave unifies those local channels natively, bills in KES, and provides 24/7 local phone/WhatsApp support."}]})}export{p as ServiceDesk};
